import { Cell } from '@ton/core';

const INIT_CODE_BASE64 = {
  router: process.env.ROUTER_CODE,
  pool: process.env.POOL_CODE,
  account: process.env.ACCOUNT_CODE,
  positionnft: process.env.POSITION_CODE,
  distributor:
    '',
  user_distributor:
    '',
};

export const ROUTERV3_CODE = Cell.fromBase64(INIT_CODE_BASE64.router);
export const ACCOUNTV3_CODE = Cell.fromBase64(INIT_CODE_BASE64.account);
export const POSITIONV3_CODE = Cell.fromBase64(INIT_CODE_BASE64.positionnft);
export const POOLV3_CODE = Cell.fromBase64(INIT_CODE_BASE64.pool);

export const DISTRIBUTOR_CODE = Cell.fromBase64(INIT_CODE_BASE64.distributor);
export const USER_DISTRIBUTOR_CODE = Cell.fromBase64(
  INIT_CODE_BASE64.user_distributor
);
